/**
 * real-first-open — desensitized tail-20-turns snapshots replayed from a
 * REAL persisted session wire (main: 249 turns / 438 tasks / 343 subagent
 * tasks in the tail window; plus four subagent wires), served as the
 * first-open transcript.reset frames so the GUI renders the true first-open
 * scale (500+ blocks on main) and real agent-page shapes instead of a
 * synthetic miniature.
 *
 * The sample JSON lives in ../.tmp/real-replay/ (gitignored, regenerated by
 * .tmp/replay-real-agents.mts from the real wire.jsonl files); text is
 * masked with length-preserving filler, structure/ids/timings intact.
 */

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { sessionRecord } from './helpers.mjs';

const SID = 'session_fixture_real_first_open';

const sample = JSON.parse(
  readFileSync(
    join(dirname(fileURLToPath(import.meta.url)), '..', '.tmp', 'real-replay', 'real-agents-sample.json'),
    'utf8',
  ),
);

export default {
  sessions: [sessionRecord(SID, { title: 'Fixture: real first-open (desensitized)' })],
  snapshots: {
    [SID]: {
      messages: [],
      has_more: true,
      subagents: sample.roster,
      agent_transcripts: {
        main: sample.main,
        ...sample.agents,
      },
    },
  },
};
